import re

from moler.exceptions import CommandFailure, ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand

__author__ = "Adrianna Pienkowska"
__copyright__ = "Copyright (C) 2018, Nokia"
__email__ = "adrianna.pienkowska@nokia.com"


class FileUpload(GenericEMSSIMCommand):
    """Fileupload command class."""

    def __init__(self, connection, file_type, prompt=None, newline_chars=None, runner=None):
        """
        Fileupload command.

        :param connection: moler connection to device, terminal when command is executed.
        :param file_type: number of type upload filer
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(FileUpload, self).__init__(connection, prompt=prompt, newline_chars=newline_chars, runner=runner)
        self.file_type = file_type
        self._flag_on_file_path = False
        self.current_ret["FILE DETAILS"] = {}

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        return f"file_upload {self.file_type}"

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_file_details(line)
                self._parse_file_path_flag(line)
                self._parse_file_path(line)
                self._parse_error(line)
            except ParsingDone:
                pass
        return super(FileUpload, self).on_new_line(line, is_full_line)

    _re_file_details = re.compile(r"\|\s+(?P<KEY>.*)=>(?P<VALUE>.*)")

    def _parse_file_details(self, line):
        if self._regex_helper.search_compiled(FileUpload._re_file_details, line):
            key = self._regex_helper.group("KEY").strip()
            value = self._regex_helper.group("VALUE").strip()
            self.current_ret["FILE DETAILS"].update({key: value})
            raise ParsingDone

    _re_file_path_flag = re.compile(r"(?P<FILE>File stored at following path:)")

    def _parse_file_path_flag(self, line):
        if self._regex_helper.search_compiled(FileUpload._re_file_path_flag, line):
            self._flag_on_file_path = True
            raise ParsingDone

    _re_file_path = re.compile(r"\d+:\d+:\d+\s+\|\s+(?P<FILE_PATH>.*)")

    def _parse_file_path(self, line):
        if self._regex_helper.search_compiled(FileUpload._re_file_path, line) and self._flag_on_file_path:
            key = "path"
            value = self._regex_helper.group("FILE_PATH").strip()
            self.current_ret["FILE DETAILS"].update({key: value})
            self._flag_on_file_path = False
            raise ParsingDone

    _re_error = re.compile(r"ERROR:\s(?P<ERROR_MSG>.*)")

    def _parse_error(self, line):
        if self._regex_helper.search_compiled(FileUpload._re_error, line):
            self.set_exception(CommandFailure(self, f"ERROR: {self._regex_helper.group('ERROR_MSG')}"))
            raise ParsingDone


